// Costo de distribución: 100 envíos que hay que cotizar.
const http = require('http');
const srv = http.createServer((req, res) => {
  const u = new URL(req.url, 'http://x');
  res.setHeader('content-type', 'application/json');
  if (u.pathname === '/lote') {
    let b = ''; req.on('data', d => b += d);
    req.on('end', () => res.end(JSON.stringify(JSON.parse(b).kms.map(km => 1200 + km * 85))));
  } else {
    res.end(JSON.stringify(1200 + Number(u.searchParams.get('km')) * 85));
  }
}).listen(24717);

const agent = new http.Agent({ keepAlive: true });
const get = (km) => new Promise((ok) => http.get(`http://127.0.0.1:24717/?km=${km}`, { agent }, r => {
  let b = ''; r.on('data', d => b += d); r.on('end', () => ok(JSON.parse(b)));
}));
const post = (kms) => new Promise((ok) => {
  const q = http.request('http://127.0.0.1:24717/lote', { method: 'POST', agent }, r => {
    let b = ''; r.on('data', d => b += d); r.on('end', () => ok(JSON.parse(b)));
  });
  q.end(JSON.stringify({ kms }));
});
const ms = (t0) => (Number(process.hrtime.bigint() - t0) / 1e6).toFixed(1);

(async () => {
  const kms = Array.from({ length: 100 }, (_, i) => 3 + (i * 7) % 40);
  for (let i = 0; i < 50; i++) await get(10); // calentar
  let t0 = process.hrtime.bigint();
  const local = kms.map(km => 1200 + km * 85);
  console.log('A) funcion local, 100 envios:           ' + ms(t0) + ' ms');
  t0 = process.hrtime.bigint();
  const unoAUno = [];
  for (const km of kms) unoAUno.push(await get(km));
  console.log('B) 100 pedidos HTTP, uno por envio:      ' + ms(t0) + ' ms');
  t0 = process.hrtime.bigint();
  const lote = await post(kms);
  console.log('C) 1 pedido HTTP con los 100 envios:     ' + ms(t0) + ' ms');
  console.log('mismas respuestas: ' + (JSON.stringify(local) === JSON.stringify(unoAUno) && JSON.stringify(local) === JSON.stringify(lote)));
  process.exit(0);
})();

// Registro INVENTADO de 12 entregas de una empresa de logística.
// Cada línea: qué servicios hubo que publicar en la misma ventana porque
// uno no funcionaba sin la versión nueva del otro.
const servicios = ['tarifas', 'despachos', 'clientes', 'facturacion', 'rutas', 'avisos'];
const entregas = [
  ['tarifas'], ['avisos'], ['rutas'],
  ['despachos', 'clientes'],
  ['despachos', 'clientes', 'tarifas'],
  ['facturacion'],
  ['clientes', 'facturacion'],
  ['despachos', 'tarifas'],
  ['rutas', 'despachos'],
  ['avisos'], ['tarifas'],
  ['clientes', 'facturacion', 'despachos'],
];
// Unión de conjuntos: los servicios que alguna vez salieron juntos quedan en el mismo grupo.
const padre = Object.fromEntries(servicios.map(s => [s, s]));
const raiz = (s) => padre[s] === s ? s : (padre[s] = raiz(padre[s]));
for (const e of entregas) for (const s of e.slice(1)) padre[raiz(s)] = raiz(e[0]);
const grupos = {};
for (const s of servicios) (grupos[raiz(s)] ||= []).push(s);
const solas = entregas.filter(e => e.length === 1).length;
console.log('entregas de un solo servicio: ' + solas + ' de ' + entregas.length);
for (const g of Object.values(grupos)) console.log('grupo que sale junto: ' + g.join(', '));
